'use client';
import { useState } from 'react';

export default function NewInqForm() {
  const [company, setCompany] = useState<string | null>(null);
  const [rawText, setRawText] = useState<string>('');

  return (
    <form
      onSubmit={async (e) => {
        e.preventDefault();
        console.log('Submitting new inquiry:', { company, rawText });
      }}
    >
      <div>
        <label htmlFor="company">Firma:</label>
        <input
          id="company"
          type="text"
          value={company ?? ''}
          onChange={(e) => setCompany(e.target.value || null)}
        />
      </div>
      <div>
        <label htmlFor="rawText">Tekst zapytania:</label>
        <textarea
          id="rawText"
          value={rawText}
          onChange={(e) => setRawText(e.target.value)}
        />
      </div>
      <button type="submit">Dodaj zapytanie</button>
    </form>
  );
}